    "title": "Mini OLED Dashboard: Your Personal Data Screen",
    "description": "Build a professional mini dashboard using a 0.96-inch OLED display. In this experiment, you'll display live temperature, humidity, soil moisture, and system uptime on a compact screen. Learn how to communicate with I2C devices and create multiple dashboard screens using a push button.",
    "code": "/*\n * EXPERIMENT 9: Mini OLED Dashboard\n * EZCirkit Learning Kit\n *\n * Displays a multi-sensor dashboard on the 0.96\" OLED screen.\n * Shows: Temperature, Humidity, Soil Moisture, System Uptime\n * Button cycles between display screens.\n *\n * Required Libraries:\n *   - Adafruit_SSD1306\n *   - Adafruit_GFX\n *   - DHT sensor library\n *\n * I2C Pins: SDA=A4, SCL=A5 (Arduino UNO hardware I2C)\n * OLED I2C Address: 0x3C (most common — change if display blank)\n */\n\n#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n#include <DHT.h>\n\n// OLED display size\n#define SCREEN_WIDTH  128\n#define SCREEN_HEIGHT  64\n#define OLED_RESET     -1       // No reset pin used\n#define SCREEN_ADDRESS 0x3C     // I2C address (try 0x3D if display blank)\n\n// Create display object\nAdafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, OLED_RESET);\n\n// DHT sensor\n#define DHT_PIN  2\n#define DHT_TYPE DHT11\nDHT dht(DHT_PIN, DHT_TYPE);\n\n// Other pins\nconst int MOISTURE_PIN = A0;\nconst int BUTTON_PIN   = 4;\n\n// Sensor calibration\nconst int DRY_VALUE = 850;\nconst int WET_VALUE = 300;\n\n// Screen management\nint currentScreen = 0;      // 0=Main, 1=Temperature, 2=Soil, 3=Uptime\nconst int NUM_SCREENS = 4;\nbool lastButtonState = HIGH;\n\n// Sensor data storage\nfloat temperature  = 0;\nfloat humidity     = 0;\nint   soilPercent  = 0;\n\n// Function: Read all sensors and update stored values\nvoid readAllSensors() {\n  float t = dht.readTemperature();\n  float h = dht.readHumidity();\n\n  if (!isnan(t)) temperature = t;\n  if (!isnan(h)) humidity    = h;\n\n  int raw = analogRead(MOISTURE_PIN);\n  soilPercent = constrain(map(raw, DRY_VALUE, WET_VALUE, 0, 100), 0, 100);\n}\n\n// Function: Draw a progress bar on OLED\nvoid drawBar(int x, int y, int width, int height, int percent) {\n  display.drawRect(x, y, width, height, WHITE);  // Outer border\n  int fill = map(percent, 0, 100, 0, width - 4); // Inner fill width\n  display.fillRect(x + 2, y + 2, fill, height - 4, WHITE); // Fill bar\n}\n\n// Screen 0: Main overview — all data at once\nvoid drawMainScreen() {\n  display.clearDisplay();\n\n  // Header\n  display.setTextSize(1);\n  display.setTextColor(WHITE);\n  display.setCursor(20, 0);\n  display.print(\"EZCirkit Dashboard\");\n\n  // Separator line\n  display.drawLine(0, 10, 127, 10, WHITE);\n\n  // Temperature\n  display.setCursor(0, 14);\n  display.print(\"Temp:\");\n  display.setCursor(35, 14);\n  display.print(temperature, 1);\n  display.print(\" C\");\n\n  // Humidity\n  display.setCursor(0, 25);\n  display.print(\"Humi:\");\n  display.setCursor(35, 25);\n  display.print(humidity, 1);\n  display.print(\" %\");\n\n  // Soil\n  display.setCursor(0, 36);\n  display.print(\"Soil:\");\n  display.setCursor(35, 36);\n  display.print(soilPercent);\n  display.print(\" %\");\n  drawBar(70, 36, 55, 8, soilPercent);\n\n  // Screen indicator dots at bottom\n  for (int i = 0; i < NUM_SCREENS; i++) {\n    if (i == currentScreen) {\n      display.fillCircle(52 + i * 10, 60, 3, WHITE);  // Filled = current\n    } else {\n      display.drawCircle(52 + i * 10, 60, 3, WHITE);  // Outline = other\n    }\n  }\n\n  display.display();  // Push buffer to screen — REQUIRED!\n}\n\n// Screen 1: Large temperature display\nvoid drawTempScreen() {\n  display.clearDisplay();\n  display.setTextSize(1);\n  display.setCursor(25, 0);\n  display.print(\"TEMPERATURE\");\n  display.drawLine(0, 10, 127, 10, WHITE);\n\n  // Large number\n  display.setTextSize(3);\n  display.setCursor(15, 20);\n  display.print(temperature, 1);\n  display.setTextSize(2);\n  display.print(\"C\");\n\n  // Comfort label\n  display.setTextSize(1);\n  display.setCursor(30, 55);\n  if (temperature > 35) display.print(\"Too Hot!\");\n  else if (temperature < 15) display.print(\"Too Cold!\");\n  else display.print(\"Comfortable\");\n\n  display.display();\n}\n\n// Screen 2: Soil moisture with large bar\nvoid drawSoilScreen() {\n  display.clearDisplay();\n  display.setTextSize(1);\n  display.setCursor(20, 0);\n  display.print(\"SOIL MOISTURE\");\n  display.drawLine(0, 10, 127, 10, WHITE);\n\n  // Large percent number\n  display.setTextSize(3);\n  display.setCursor(30, 18);\n  display.print(soilPercent);\n  display.print(\"%\");\n\n  // Large progress bar\n  drawBar(10, 48, 108, 12, soilPercent);\n\n  // Status label\n  display.setTextSize(1);\n  if (soilPercent < 30) {\n    display.setCursor(35, 36);\n    display.print(\"NEEDS WATER\");\n  } else if (soilPercent > 75) {\n    display.setCursor(40, 36);\n    display.print(\"TOO WET\");\n  } else {\n    display.setCursor(45, 36);\n    display.print(\"HEALTHY\");\n  }\n\n  display.display();\n}\n\n// Screen 3: System uptime\nvoid drawUptimeScreen() {\n  display.clearDisplay();\n  display.setTextSize(1);\n  display.setCursor(35, 0);\n  display.print(\"UPTIME\");\n  display.drawLine(0, 10, 127, 10, WHITE);\n\n  unsigned long ms = millis();\n  int seconds = (ms / 1000) % 60;\n  int minutes = (ms / 60000) % 60;\n  int hours   = ms / 3600000;\n\n  display.setTextSize(2);\n  display.setCursor(20, 20);\n  if (hours < 10) display.print(\"0\");\n  display.print(hours);\n  display.print(\":\");\n  if (minutes < 10) display.print(\"0\");\n  display.print(minutes);\n  display.print(\":\");\n  if (seconds < 10) display.print(\"0\");\n  display.print(seconds);\n\n  display.setTextSize(1);\n  display.setCursor(15, 50);\n  display.print(\"HH : MM : SS\");\n\n  display.display();\n}\n\nvoid setup() {\n  pinMode(BUTTON_PIN, INPUT_PULLUP);\n  Serial.begin(9600);\n\n  // Initialize OLED display\n  if (!display.begin(SSD1306_SWITCHCAPVCC, SCREEN_ADDRESS)) {\n    Serial.println(\"ERROR: OLED display not found!\");\n    Serial.println(\"Check: VCC, GND, SDA (A4), SCL (A5) connections.\");\n    Serial.println(\"Try changing SCREEN_ADDRESS from 0x3C to 0x3D.\");\n    while (true);  // Halt — display required\n  }\n\n  dht.begin();\n\n  // Splash screen\n  display.clearDisplay();\n  display.setTextSize(2);\n  display.setTextColor(WHITE);\n  display.setCursor(10, 10);\n  display.println(\"EZCirkit\");\n  display.setTextSize(1);\n  display.setCursor(20, 35);\n  display.println(\"Learning Kit v1.0\");\n  display.setCursor(15, 50);\n  display.println(\"Initializing...\");\n  display.display();\n  delay(2000);\n\n  Serial.println(\"OLED Dashboard Ready. Press button to switch screens.\");\n}\n\nvoid loop() {\n  // Check button for screen switching (edge detection)\n  bool btnState = digitalRead(BUTTON_PIN);\n  if (btnState == LOW && lastButtonState == HIGH) {\n    currentScreen = (currentScreen + 1) % NUM_SCREENS;\n    Serial.print(\"Switched to screen: \");\n    Serial.println(currentScreen);\n    delay(50);  // Debounce\n  }\n  lastButtonState = btnState;\n\n  // Read sensors every 2.5 seconds\n  static unsigned long lastRead = 0;\n  if (millis() - lastRead > 2500) {\n    readAllSensors();\n    lastRead = millis();\n  }\n\n  // Draw current screen\n  switch (currentScreen) {\n    case 0: drawMainScreen();  break;\n    case 1: drawTempScreen();  break;\n    case 2: drawSoilScreen();  break;\n    case 3: drawUptimeScreen(); break;\n  }\n\n  delay(100);\n}\n",
